import localeEn from './common/en';
import consts from './common/consts';

export type DatepickerSelector = string | HTMLElement;

export type DatepickerLocale = {
    days: string[],
    daysShort: string[],
    daysMin: string[],
    months: string[],
    monthsShort: string[],
    today: string,
    clear: string,
    dateFormat: string,
    timeFormat: string,
    firstDay: number,
}

export type DatepickerButton = {
    content: string | ((dp: any) => string),
    tagName?: keyof HTMLElementTagNameMap,
    className?: string,
    attrs?: Record<string, string>,
    onClick?: (dp: any) => void
}

export type DatepickerButtonPresets = 'clear' | 'today';
export type DatepickerPosition = 'left' | 'left top' | 'left bottom' | 'top' | 'top left' | 'top right' | 'right' | 'right top' | 'right bottom' | 'bottom' | 'bottom left' | 'bottom right';
export type DatepickerViews = 'days' | 'months' | 'years';
export type DatepickerViewsSingle = 'day' | 'month' | 'year';
export type DatepickerDate = string | number | Date;
export type DatepickerNavEntry = string | ((dp: any) => string);
export type DatepickerDecade = [number, number];

export type DatepickerPositionCallback = (params: {
    $datepicker: HTMLDivElement,
    $target: HTMLInputElement,
    $pointer: HTMLElement,
    isViewChange: boolean,
    done: () => void
}) => void | (() => void);

export type DatepickerOptions<E extends HTMLElement = HTMLInputElement> = {
    classes?: string;
    inline?: boolean;
    locale?: Partial<DatepickerLocale>;
    startDate?: DatepickerDate;
    firstDay?: number | string;
    isMobile?: boolean;
    visible?: boolean;
    weekends?: [number, number];
    dateFormat?: string | ((d: Date) => string);
    altField?: DatepickerSelector;
    altFieldDateFormat?: string;
    toggleSelected?: boolean | (({datepicker, date}:{datepicker: any, date: Date}) => boolean);
    keyboardNav?: boolean;
    selectedDates?:  DatepickerDate[] | false;
    container?: DatepickerSelector;
    position?: DatepickerPosition | DatepickerPositionCallback;
    offset?: number;
    view?: DatepickerViews;
    minView?: DatepickerViews;
    showOtherMonths?: boolean;
    selectOtherMonths?: boolean;
    moveToOtherMonthsOnSelect?: boolean;
    showOtherYears?: boolean;
    selectOtherYears?: boolean;
    moveToOtherYearsOnSelect?: boolean;
    minDate?: DatepickerDate | false;
    maxDate?: DatepickerDate | false;
    disableNavWhenOutOfRange?: boolean;
    multipleDates?: number | boolean;
    multipleDatesSeparator?: string;
    range?: boolean;
    dynamicRange?: boolean;
    buttons?: DatepickerButtonPresets | DatepickerButton | (DatepickerButtonPresets | DatepickerButton)[] | false;
    monthsField?: keyof DatepickerLocale;
    showEvent?: string;
    autoClose?: boolean;
    prevHtml?: string;
    nextHtml?: string;
    navTitles?: {
        days?: DatepickerNavEntry;
        months?: DatepickerNavEntry;
        years?: DatepickerNavEntry;
    };
    timepicker?: boolean;
    onlyTimepicker?: boolean;
    dateTimeSeparator?: string;
    timeFormat?: string;
    minHours?: number;
    maxHours?: number;
    minMinutes?: number;
    maxMinutes?: number;
    hoursStep?: number;
    minutesStep?: number;
    fixedHeight?: boolean;
    onSelect?: (params: {date: Date | Date[], formattedDate: string | string[], datepicker: any}) => void;
    onChangeViewDate?: (params: {month: number, year: number, decade: DatepickerDecade}) => void;
    onChangeView?: (view: DatepickerViews) => void;
    onRenderCell?: (params: {date: Date, cellType: any, datepicker: any}) => ({
        disabled?: boolean,
        classes?: string,
        html?: string,
        attrs?: Record<string, string | number | undefined>
    } | void);
    onShow?: (isAnimationComplete: boolean) => void;
    onHide?: (isAnimationComplete: boolean) => void;
    onClickDayName?: (params: {dayIndex: number, datepicker: any}) => void;
    onBeforeSelect?: (params: {date: Date, datepicker: any}) => boolean;
    onFocus?: (params: {date: Date, datepicker: any}) => void;
}

const defaults: DatepickerOptions = {
    classes: '',
    inline: false,
    locale: localeEn,
    startDate: new Date(),
    firstDay: '',
    weekends: [6, 0],
    dateFormat: '',
    altField: '',
    altFieldDateFormat: 'T',
    toggleSelected: true,
    keyboardNav: true,
    selectedDates: [],
    container: '',
    isMobile: false,
    visible: false,
    position: 'bottom left',
    offset: 12,
    view: consts.days,
    minView: consts.days,
    showOtherMonths: true,
    selectOtherMonths: true,
    moveToOtherMonthsOnSelect: true,
    showOtherYears: true,
    selectOtherYears: true,
    moveToOtherYearsOnSelect: true,
    minDate: '',
    maxDate: '',
    disableNavWhenOutOfRange: true,
    multipleDates: false, 
    multipleDatesSeparator: ', ',
    range: false,
    dynamicRange: true,
    buttons: false,
    monthsField: 'monthsShort',
    showEvent: 'focus',
    autoClose: false,
    fixedHeight: false,
    prevHtml: '<svg><path d="M 17,12 l -5,5 l 5,5"></path></svg>',
    nextHtml: '<svg><path d="M 14,12 l 5,5 l -5,5"></path></svg>',
    navTitles: {
        days: 'MMMM, <i>yyyy</i>',
        months: 'yyyy',
        years: 'yyyy1 - yyyy2'
    },
    timepicker: false,
    onlyTimepicker: false,
    dateTimeSeparator: ' ',
    timeFormat: '',
    minHours: 0,
    maxHours: 24,
    minMinutes: 0,
    maxMinutes: 59,
    hoursStep: 1,
    minutesStep: 1,
    onSelect: undefined,
    onChangeViewDate: undefined,
    onChangeView: undefined,
    onRenderCell: undefined,
    onShow: undefined,
    onHide: undefined,
    onClickDayName: undefined,
};

export default defaults;